#!/usr/bin/env node
/**
 * generate-locators.mjs — codegen from the exported UI model.
 *
 * Reads the UI-model build_artifact (out/ui_model/shopcheck/*.yaml — the
 * single source of truth for locators) and emits e2e/locators.generated.ts,
 * the typed module every page object imports. Route paths are resolved from
 * tools/ui_model_routes.yaml (the exporter's hand-maintained seam) so the
 * harness never hand-copies a URL either.
 *
 * Run after every UI-model re-export:   npm run generate:locators
 * The generated file IS committed (out/ is gitignored, so a fresh clone has
 * no model to read at test time); regenerating keeps it in lockstep.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '..', '..');
const modelDir = process.env.UI_MODEL_DIR ?? join(repoRoot, 'out', 'ui_model', 'shopcheck');
const routesFile = join(repoRoot, 'tools', 'ui_model_routes.yaml');
const outFile = join(here, '..', 'locators.generated.ts');

if (!existsSync(modelDir)) {
  console.error(
    `UI model not found at ${modelDir}\n` +
    `Export it first:  python tools/export_ui_model.py  (from the repo root, ` +
    `with the app runnable)\nOr point UI_MODEL_DIR at an exported model.`,
  );
  process.exit(1);
}

const manifest = parse(readFileSync(join(modelDir, '_manifest.yaml'), 'utf8'));
const routesDoc = parse(readFileSync(routesFile, 'utf8'));
const routeByPageObject = Object.fromEntries(
  routesDoc.pages.map((p) => [p.page_object, p.route]),
);

const camel = (s) => s.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());

function convertSpec(spec) {
  const out = { by: spec.by };
  if (spec.value !== undefined) out.value = spec.value;
  if (spec.role !== undefined) out.role = spec.role;
  if (spec.name !== undefined) out.name = spec.name;
  return out;
}

function convertElement(el) {
  const out = { preferred: convertSpec(el.preferred) };
  if (el.fallback) out.fallback = convertSpec(el.fallback);
  if (el.conditional) out.conditional = true;
  return out;
}

const pages = {};
const pageFiles = readdirSync(modelDir)
  .filter((f) => f.endsWith('.yaml') && !['_manifest.yaml', 'test_data.yaml'].includes(f))
  .sort();

for (const file of pageFiles) {
  const doc = parse(readFileSync(join(modelDir, file), 'utf8'));
  const route = routeByPageObject[doc.page_object];
  if (!route) {
    console.error(`No route for page_object '${doc.page_object}' in ${routesFile}`);
    process.exit(1);
  }
  const elements = {};
  for (const [name, el] of Object.entries(doc.elements ?? {})) {
    elements[camel(name)] = convertElement(el);
  }
  const templates = {};
  for (const [name, tmpl] of Object.entries(doc.element_templates ?? {})) {
    templates[camel(name)] = {
      ...convertElement(tmpl),
      param: tmpl.param,
      paramSource: tmpl.param_source,
    };
  }
  pages[doc.page_object] = {
    pageObject: doc.page_object,
    urlPathKey: doc.url_path_key,
    path: route,
    description: doc.description,
    ...(doc.shared ? { shared: true } : {}),
    elements,
    templates,
  };
}

const rawTestData = parse(readFileSync(join(modelDir, 'test_data.yaml'), 'utf8'));
const testData = {
  users: Object.fromEntries(
    Object.entries(rawTestData.users).map(([persona, u]) => [
      persona,
      { usernameKey: u.username_key, behavior: u.behavior },
    ]),
  ),
  products: rawTestData.products,
  orders: rawTestData.orders,
};

const banner = `/**
 * AUTO-GENERATED — DO NOT EDIT.
 *
 * Generated by scripts/generate-locators.mjs from the exported UI model
 * (out/ui_model/shopcheck, source_sha: ${manifest.source_sha}, generated_at:
 * ${manifest.generated_at}). The UI model is the single source of truth for
 * locators; regenerate this file after every model re-export:
 *
 *     npm run generate:locators
 */
import type { PageModel, TestDataModel } from './model/types';

`;

const body =
  `export const UI_MODEL_SOURCE_SHA = ${JSON.stringify(String(manifest.source_sha))};\n\n` +
  `export const pages = ${JSON.stringify(pages, null, 2)} as const satisfies Record<string, PageModel>;\n\n` +
  `export const testData = ${JSON.stringify(testData, null, 2)} as const satisfies TestDataModel;\n\n` +
  `/** Seeded closed sets for per-item element templates. */\n` +
  `export const seededProductIds = testData.products.map((p) => p.id);\n` +
  `export const seededOrderIds = testData.orders.map((o) => o.id);\n`;

writeFileSync(outFile, banner + body);
console.log(
  `Wrote ${outFile}\n  pages: ${Object.keys(pages).join(', ')}\n` +
  `  model source_sha: ${manifest.source_sha}`,
);
